import numpy as np
def equation(eps, T, params):
    p = params
    base = p[0] + p[1]*T + p[2]*T**2
    amp = p[3] + p[4]*T + p[5]*T**2
    return base + amp*(eps+p[6])**(p[7]+p[8]*T)

